package com.emos.platform.telemetry;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class InteractionSessionServiceTest{
 @Test void counts_only_visible_active_heartbeats_within_idle_cutoff_and_deduplicates(){var store=new MemoryStore();var service=new InteractionSessionService(store,Duration.ofSeconds(120));var start=Instant.parse("2026-10-04T10:00:00Z");var id=service.start(UUID.randomUUID(),start);service.heartbeat(id,start.plusSeconds(60),true);service.heartbeat(id,start.plusSeconds(60),true);service.heartbeat(id,start.plusSeconds(120),false);service.heartbeat(id,start.plusSeconds(300),true);service.heartbeat(id,start.plusSeconds(360),true);service.stop(id,start.plusSeconds(420));assertThat(store.get(id).activeSeconds()).isEqualTo(120);}
 @Test void records_only_timing_and_case_identity(){var store=new MemoryStore();var service=new InteractionSessionService(store,Duration.ofSeconds(120));var caseId=UUID.randomUUID();var id=service.start(caseId,Instant.EPOCH);assertThat(store.get(id)).extracting(SessionRecord::caseId,SessionRecord::activeSeconds).containsExactly(caseId,0L);}
 static class MemoryStore implements InteractionSessionStore{Map<UUID,SessionRecord> values=new HashMap<>();Set<String> heartbeats=new HashSet<>();public SessionRecord insert(SessionRecord r){values.put(r.id(),r);return r;}public SessionRecord get(UUID id){return values.get(id);}public boolean addHeartbeat(UUID id,Instant at,boolean visible){return heartbeats.add(id+":"+at);}public void update(SessionRecord r){values.put(r.id(),r);}}
}
